// ascii
(function() {
	"use strict";
	
	let asciisize = 3;
	let asciiquality = 4;
	let asciicolor = false;
	let asciichars = ['@', '#', '+', "'", ';', ':', ',', '.', '`'];
	let asciicolorChar = ['B', 'A', 'C', "H", 'O', 'R', 'S'];
	let asciimaxFilesize = 2500000;
	let asciicanvas = null;
	let asciictx = null;
	let asciiimageData = null;
	let asciiwidth = 0;
	let asciiheight = 0;
	let asciiimgLoaded = false;
	let asciifile = null;
	let output = "";

	function ascii_loadImage() {
		return new Promise((resolve, reject) => {
			const img = new Image();
			img.onload = () => {
				asciiwidth = img.width;
				asciiheight = img.height;
				asciicanvas = document.createElement('canvas');
				asciicanvas.width = asciiwidth;
				asciicanvas.height = asciiheight;
				asciictx = asciicanvas.getContext('2d');
				asciictx.drawImage(img, 0, 0);
				asciiimageData = asciictx.getImageData(0, 0, asciiwidth, asciiheight);
				asciiimgLoaded = true;
				resolve(true);
				document.getElementById("ascii-pre").innerHTML = asciidraw();
			};
			img.onerror = () => {
				asciiimgLoaded = false;
				resolve(false)
			};
			img.src = asciifile
		})
	}

	function asciierror(message) {
		return message
	}

	function ascii_getPixel(x, y) {
		const idx = (y * asciiwidth + x) * 4;
		const d = asciiimageData.data;
		return {
			red: d[idx],
			green: d[idx + 1],
			blue: d[idx + 2],
			alpha: d[idx + 3]
		}
	}

	function ascii_samePixel(a, b) {
		return a.red === b.red && a.green === b.green && a.blue === b.blue
	}

	function asciidraw() {
		if (!asciiimgLoaded) {
			return asciierror('Data not valid!')
		}
		output = '';
		if (asciicolor === true) {
			const firstPixel = ascii_getPixel(1, 1);
			output = `<span style="color: ${rgbToHex(firstPixel.red, firstPixel.green, firstPixel.blue)};">`
		}
		let colorChar = "#", lg = 0, hit = 0;
		if(asciicolorChar.length){
			lg = asciicolorChar.length - 1;
			colorChar = asciicolorChar[hit];
		}
		for (let y = 0; y < asciiheight; y += asciiquality) {
			for (let x = 0; x < asciiwidth; x += asciiquality) {
				const rgb = ascii_getPixel(x, y);
				let char;
				if (asciicolor === true) {
					if (x > asciiquality && y > asciiquality && ascii_samePixel(rgb, ascii_getPixel(x - asciiquality, y))) {
						char = colorChar
					} else {
						char = `</span><span style="color: ${rgbToHex(rgb.red, rgb.green, rgb.blue)};">${colorChar}`
					}
					if(hit < lg){
						hit = hit+1;
					}else{
						hit = 0;
					}
					colorChar = asciicolorChar[hit];
				} else {
					const brightness = rgb.red + rgb.green + rgb.blue;
					const level = Math.round(brightness / (765 / (asciichars.length - 1)));
					char = asciichars[level]
				}
				output += char
			}
			output += '\n'
		}
		if (asciicolor === true) {
			output += '</span>'
		}
		return `<pre style="line-height: 0.6 !important;font: ${asciisize * 2}px/${asciisize}px monospace;">${output}</pre>`
	}

	function rgbToHex(red, green, blue) {
		const toHex = (v) => v.toString(16).padStart(2, '0');
		return `#${toHex(red)}${toHex(green)}${toHex(blue)}`
	}

	function asciireadFile(e) {
		var t = e.target.files[0];
		if (t)
			if (/(jpe?g|png)$/i.test(t.type))
				if (t.size < asciimaxFilesize) {
					document.getElementById("ascii-res").style.display = "";
					var l = new FileReader;
					l.onload = function(e) {
						asciifile = e.target.result;
						document.getElementById("ascii-sc").src = asciifile;
						ascii_loadImage();
					}, l.readAsDataURL(t)
				} else alert("File size is big");
		else alert("Failed file type");
		else alert("Failed to load file")
	}

	async function asciicopy(e,n){try{await navigator.clipboard.writeText(n),e.innerHTML='Copied!',setTimeout(()=>e.innerHTML='Copy text',1e3)}catch(e){alert("Failed to copy text.")}}
	
	document.getElementById("ascii_img").addEventListener("change", asciireadFile, !1);

	document.getElementById("ascii-w").addEventListener("change", function() {
		asciisize = this.value;
		ascii_loadImage();
	});

	document.getElementById("ascii-q").addEventListener("change", function() {
		asciiquality = parseInt(this.value);
		ascii_loadImage();
	});

	document.getElementById("ascii-colored").addEventListener("change", function() {
		if(this.checked){
			asciicolor = true;
			document.getElementById("ascii-chars").value = asciicolorChar.join("");
			document.getElementById("ascii-nt").style.display = "none";
			document.getElementById("ascii-kopi").style.display = "none";
		}else{
			asciicolor = false;
			document.getElementById("ascii-chars").value = asciichars.join("");
			document.getElementById("ascii-nt").style.display = "";
			document.getElementById("ascii-kopi").style.display = "";
		}
		ascii_loadImage();
	});

	document.getElementById("ascii-chars").addEventListener("change", function() {
		if(asciicolor){
			asciicolorChar = this.value.trim().split("");
		}else{
			asciichars = this.value.trim().split("");
		}
		ascii_loadImage();
	});

	document.getElementById("ascii-hex1").addEventListener("change", function() {
		document.getElementById("ascii-cpx1").value = this.value;
		document.getElementById("ascii-pre").style.background = this.value;
	});

	document.getElementById("ascii-cpx1").addEventListener("change", function() {
		document.getElementById("ascii-hex1").value = this.value;
		document.getElementById("ascii-pre").style.background = this.value;
	});

	document.getElementById("ascii-hex2").addEventListener("change", function() {
		document.getElementById("ascii-cpx2").value = this.value;
		document.getElementById("ascii-pre").style.color = this.value;
	});

	document.getElementById("ascii-cpx2").addEventListener("change", function() {
		document.getElementById("ascii-hex2").value = this.value;
		document.getElementById("ascii-pre").style.color = this.value;
	});

	document.getElementById("ascii-kopi").addEventListener("click", function() {
		asciicopy(this, output);
	});

})();

